INSERT INTO subject (subject_id,course_id,subject_name,subject_desc,note_name,note_url,is_delete,is_active,created_by,created_date,modified_by,modified_date,ip_address) VALUES ('91','33','English grammer','English grammar is the set of structural rules of the English language. This includes the structure of words, phrases, clauses, sentences, and whole texts.','grammer.pdf','notes/1696073557003.pdf','0','1',NULL,'2023-09-29 14:41:07',NULL,'2023-09-30 17:02:37',NULL);
