INSERT INTO note (note_id,subject_id,note_name,note_path,note_desc,note_extension,is_delete,is_active,created_by,created_date,modified_by,modified_date,ip_address) VALUES ('318','87','English vocabulary-opposite  word','notes/1695978856316.pdf','Opposite words can be defined as pairs of words directly opposite or contradicting each other's meaning. They are also called antonyms. It is one of the most important topics in English grammar. Learning opposite words will help students understand which word to use in which context while writing, speaking or reading.','pdf','0','1',NULL,'2023-09-29 14:44:16',NULL,'2023-09-29 09:14:16',NULL);
